"""Admin console: opens with the backquote key, is locked until a passphrase is set / given, refuses online, edits the save; and the PUBLIC build has none of it.
usage: python3 test/admin.py [--shots DIR]"""
import sys, os, re
from playwright.sync_api import sync_playwright
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SHOTS = sys.argv[sys.argv.index('--shots') + 1] if '--shots' in sys.argv else None
res = []
def ok(name, cond, info=''):
    res.append(bool(cond)); print(('  ok   ' if cond else '  FAIL ') + name + (f'  [{info}]' if info != '' else ''))

# ---- static: what players get has no console ----
for f in ('site/index.html', 'trap-dungeon.artifact.html'):
    t = open(f'{ROOT}/{f}', encoding='utf-8').read()
    ok(f'{f}: no console code at all', 'setpass' not in t and 'ADM_OPEN' not in t and "box.id='adm'" not in t)
t = open(f'{ROOT}/site/index.html', encoding='utf-8').read()
ok('public build: has the gems / player-level core, but no undo store or wipe command', 'gemAdd' in t and 'plLevel' in t and 'td_undo' not in t and 'WIPE_SAFE' not in t)
for f in ('trap-dungeon.html', 'docs/index.html'):
    t = open(f'{ROOT}/{f}', encoding='utf-8').read()
    ok(f'{f}: private builds keep the console', 'setpass' in t and 'ADM_OPEN' in t)

LOG = "() => document.getElementById('adm').innerText"
def cmd(pg, line):
    pg.fill('#adm input', line); pg.press('#adm input', 'Enter'); pg.wait_for_timeout(60)

with sync_playwright() as p:
    b = p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required'])
    # ---- the public site: Backquote does nothing ----
    pg = b.new_page(viewport={'width': 960, 'height': 540}); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(f'file://{ROOT}/site/index.html'); pg.wait_for_timeout(500)
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100)
    ok('public build: backquote opens nothing', pg.evaluate("() => !document.getElementById('adm') && !window.ADM_OPEN"))
    pg.close()

    pg = b.new_page(viewport={'width': 960, 'height': 540}); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' else None)
    pg.on('requestfailed', lambda r: errs.append('REQ ' + r.url[:90]))
    pg.route('**/*firebasedatabase.app/**', lambda r: r.fulfill(status=200, content_type='application/json', body='null'))     # opening the profile writes my stats card: keep it off the real database
    pg.goto(f'file://{ROOT}/trap-dungeon.html'); pg.wait_for_timeout(500)
    pg.evaluate("localStorage.clear()"); pg.reload(); pg.wait_for_timeout(500)
    T = "window.TD"
    ok('console starts closed', pg.evaluate("() => document.getElementById('adm').style.display") == 'none')
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(120)
    ok('backquote opens it and focuses the input', pg.evaluate("() => document.getElementById('adm').style.display === 'flex' && document.activeElement === document.querySelector('#adm input')"))
    cmd(pg, 'coins 999')
    ok('locked: nothing works before a passphrase exists', pg.evaluate("() => TD.S.wallet|0") == 0 and 'setpass' in pg.evaluate(LOG))
    cmd(pg, 'setpass ab'); ok('a passphrase shorter than 3 is refused', pg.evaluate("() => typeof TD.S.admh") == 'undefined')
    cmd(pg, 'setpass secret1'); ok('setpass stores a number (hash), not the word', pg.evaluate("() => typeof TD.S.admh") == 'number' and 'secret1' not in pg.evaluate("() => localStorage.getItem('td_s')"))
    ok('the typed word is not echoed in the log', 'secret1' not in pg.evaluate(LOG))
    pg.evaluate("() => { window.__lock = 1 }")
    cmd(pg, 'lock'); cmd(pg, 'coins 5'); ok('lock locks again', pg.evaluate("() => TD.S.wallet|0") == 0)
    cmd(pg, 'auth wrong'); cmd(pg, 'coins 5'); ok('a wrong word does not unlock', pg.evaluate("() => TD.S.wallet|0") == 0)
    cmd(pg, 'auth secret1'); cmd(pg, 'coins 250'); ok('auth with the right word, then coins', pg.evaluate("() => TD.S.wallet") == 250 and pg.evaluate("() => TD.S.adm") == 1)
    cmd(pg, 'give -50'); ok('give adds (and can subtract)', pg.evaluate("() => TD.S.wallet") == 200)
    cmd(pg, 'best 12'); ok('best sets progress and fills 1-star for earlier levels', pg.evaluate("() => [TD.S.best, TD.S.cl[11], TD.S.cl[1], TD.S.cl[12]||0]") == [12, 1, 1, 0])
    cmd(pg, 'stars 3 1 5'); ok('stars sets a range', pg.evaluate("() => [1,2,3,4,5,6].map(n => TD.S.cl[n])") == [3, 3, 3, 3, 3, 1])
    cmd(pg, 'stars max'); ok('stars max covers every cleared level', pg.evaluate("() => Object.keys(TD.S.cl).filter(k => +k < TD.S.best).every(k => TD.S.cl[k] === 3)"))
    cmd(pg, 'diff hell'); ok('diff changes the setting', pg.evaluate("() => TD.S.diff") == 'hell')
    cmd(pg, 'diff nightmare'); ok('nightmare is never selectable in single player', pg.evaluate("() => TD.S.diff") == 'hell')
    cmd(pg, 'unlock heroes'); ok('unlock heroes', pg.evaluate("() => Object.keys(TD.S.own).length") >= 8)
    cmd(pg, 'unlock worlds'); ok('unlock worlds', pg.evaluate("() => Object.keys(TD.S.ow).length") >= 10)
    cmd(pg, 'unlock acc'); ok('unlock acc', pg.evaluate("() => Object.keys(TD.S.aq).length") > 10)
    cmd(pg, 'hero robot'); ok('hero selects and owns', pg.evaluate("() => TD.S.hero") == 'robot')
    cmd(pg, 'stage robot 3'); ok('stage is 1-based on the command line, 0-based in the save', pg.evaluate("() => TD.S.hs.robot") == 2)
    cmd(pg, 'stage all 1'); ok('stage all', pg.evaluate("() => Object.values(TD.S.hs).every(v => v === 0)"))
    cmd(pg, 'xp robot 30'); ok('xp', pg.evaluate("() => TD.S.hx.robot") == 30)
    # ---- gems / player xp / level / relative amounts ----
    S_ = lambda e: pg.evaluate(f"() => {e}")
    cmd(pg, 'coins 100'); cmd(pg, 'coins +30'); cmd(pg, 'coins -10'); ok('coins: plain = set, +n / -n = relative', S_('TD.S.wallet') == 120)
    cmd(pg, 'coins -9999'); ok('coins never go below 0', S_('TD.S.wallet') == 0)
    cmd(pg, 'coins abc'); ok('coins with a non-number is refused', S_('TD.S.wallet') == 0)
    cmd(pg, 'coins 500')
    ok('no gems and no xp: the HUD shows neither chip, the profile no extra tiles', S_("document.getElementById('hGem').classList.contains('hide') && document.getElementById('hPl').classList.contains('hide') && !TD.plOn()"))
    cmd(pg, 'gems 40'); cmd(pg, 'gems +10'); ok('gems set and relative', S_('TD.S.gems') == 50)
    cmd(pg, 'gems -70'); ok('gems clamp at 0', S_('TD.S.gems') == 0)
    cmd(pg, 'gems zzz'); ok('gems with a non-number is refused', S_('TD.S.gems') == 0)
    cmd(pg, 'gems 25')
    ok('gems > 0: the HUD shows a gem chip', S_("!document.getElementById('hGem').classList.contains('hide') && document.getElementById('hGem').textContent.includes('25')"))
    ok('plLevel curve: 0->1, 99->1, 100->2, 299->2, 300->3, 1000->5, huge->100', S_('[0, 99, 100, 299, 300, 1000, 1e9].map(x => TD.plLevel(x))') == [1, 1, 2, 2, 3, 5, 100])
    cmd(pg, 'xp 100'); ok('xp <n> is the PLAYER xp (one argument) and sets the level', S_('[TD.S.pxp, TD.plLevel()]') == [100, 2])
    cmd(pg, 'xp +200'); ok('xp +n is relative', S_('[TD.S.pxp, TD.plLevel()]') == [300, 3])
    cmd(pg, 'xp -999'); ok('xp clamps at 0', S_('[TD.S.pxp, TD.plLevel()]') == [0, 1])
    cmd(pg, 'level 5'); ok('level 5 puts the xp at the start of level 5', S_('[TD.S.pxp, TD.plLevel()]') == [1000, 5])
    cmd(pg, 'level +1'); ok('level +1', S_('TD.plLevel()') == 6)
    cmd(pg, 'level 0'); cmd(pg, 'level abc'); ok('level 0 / non-number refused', S_('TD.plLevel()') == 6)
    cmd(pg, 'level 9999'); ok('level clamps at 100', S_('TD.plLevel()') == 100)
    cmd(pg, 'level 3'); ok('level can go down again', S_('[TD.S.pxp, TD.plLevel()]') == [300, 3])
    ok('the HUD level chip shows 3', S_("!document.getElementById('hPl').classList.contains('hide') && document.getElementById('hPl').textContent.includes('3')"))
    ok('hero xp is untouched by player xp', S_('TD.S.hx.robot') == 30)
    ok('the stats card carries the player level', S_('TD.pfOwn().pl') == 3 and S_("TD.pfSan({pl: 500}).pl") == 100 and S_("TD.pfSan({}).pl") == 1 and S_("TD.pfSan({pl: -4}).pl") == 1)
    pg.evaluate("() => { TD.openPf() }"); pg.wait_for_timeout(300)
    ok('profile: level bar, gem + level tiles and the level ranking button appear', pg.evaluate("() => !!document.querySelector('#pfHead .pfxp') && document.querySelector('#pfStats').textContent.includes('مستوى اللاعب') && document.querySelector('#pfStats').textContent.includes('جواهر') && !document.querySelector('#pfMet [data-m=pl]').classList.contains('hide') && document.getElementById('pfW').textContent.includes('25')"))
    pg.evaluate("() => { TD.closePf() }"); pg.wait_for_timeout(100)
    # daily / weekly / date
    cmd(pg, 'daily'); ok('daily lists the 3 tasks', '/' in pg.evaluate(LOG).split('تحدّيات اليوم')[-1])
    w1 = S_('TD.S.wallet'); cmd(pg, 'daily done'); ok('daily done completes + pays every task (and the bonus)', S_('Object.keys(TD.S.dy.c).length') == 3 and S_('TD.S.dy.a') == 1 and S_('TD.S.wallet') > w1 + 50)
    d0 = S_('TD.S.dy.d'); cmd(pg, 'daily reset'); ok('daily reset gives fresh progress for the same day', S_('Object.keys(TD.S.dy.c).length') == 0 and S_('TD.S.dy.a') == 0 and S_('TD.S.dy.d') == d0)
    cmd(pg, 'weekly done'); ok('weekly done', S_('Object.keys(TD.S.wk.c).length') == 3)
    cmd(pg, 'date +1'); ok('date +1 moves the game one day on (new daily set)', S_('TD.S.dy.d') == d0 + 1 and S_('TD.dayNum()') == d0 + 1)
    cmd(pg, 'date +7'); ok('date +7 crosses into a new week', S_('Object.keys(TD.S.wk.c).length') == 0)
    cmd(pg, 'date now'); ok('date now comes back', S_('TD.S.dy.d') == d0 and S_('ADM_OPEN && true'))
    cmd(pg, 'date 99999'); ok('absurd date offsets are refused', S_('TD.S.dy.d') == d0)
    cmd(pg, 'wipe'); ok('wipe with no argument lists the groups and changes nothing', 'gems' in pg.evaluate(LOG) and S_('TD.S.gems') == 25)
    cmd(pg, 'wipe heroes'); ok('wipe heroes is refused without yes', S_('Object.keys(TD.S.own).length') >= 8)
    cmd(pg, 'wipe nonsense yes'); ok('unknown wipe group refused', S_('Object.keys(TD.S.own).length') >= 8)
    cmd(pg, 'coins 888'); cmd(pg, 'coins 12'); cmd(pg, 'gems 7')
    ok('undo store keeps at most the last 3 snapshots, none of them has the console word', pg.evaluate("() => { const a = JSON.parse(localStorage.getItem('td_undo') || '[]'); return a.length === 3 && !a.join('').includes('secret1') }"))
    cmd(pg, 'goto 3'); pg.wait_for_timeout(300)
    ok('goto starts the level and closes the console', pg.evaluate("() => TD.G.level === 3 && TD.G.state === 'play'") and pg.evaluate("() => document.getElementById('adm').style.display") == 'none')
    # god / speed / kill / win
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100)
    ok('the game is frozen while the console is open', pg.evaluate("() => { const t0 = TD.G.t; return new Promise(r => setTimeout(() => r(TD.G.t === t0), 400)) }"))
    cmd(pg, 'god on'); pg.keyboard.press('Backquote'); pg.wait_for_timeout(100)
    pg.evaluate("() => TD.die('spike', null)"); ok('god: a spike does nothing', pg.evaluate("() => TD.G.state") == 'play')
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100); cmd(pg, 'god off'); pg.keyboard.press('Backquote'); pg.wait_for_timeout(100)
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100); cmd(pg, 'kill'); ok('kill', pg.evaluate("() => TD.G.state") == 'dead')
    pg.evaluate("() => { TD.retry(); TD.G.state = 'play' }"); pg.wait_for_timeout(100)
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100); cmd(pg, 'speed 2'); pg.keyboard.press('Backquote'); pg.wait_for_timeout(100)
    ok('speed 2 runs the game faster', pg.evaluate("() => { const t0 = TD.G.t; return new Promise(r => setTimeout(() => r(TD.G.t - t0), 1000)) }") > 1.5)
    pg.keyboard.press('Backquote'); pg.wait_for_timeout(100); cmd(pg, 'speed 1')
    cmd(pg, 'tp 20'); ok('tp moves the player', abs(pg.evaluate("() => TD.P.x") - 640) < 2)
    cmd(pg, 'win'); pg.wait_for_timeout(200); ok('win finishes the level', pg.evaluate("() => TD.G.state") == 'win')
    if SHOTS:
        os.makedirs(SHOTS, exist_ok=True); pg.keyboard.press('Backquote'); pg.wait_for_timeout(100); cmd(pg, 'help'); pg.locator('#stage').screenshot(path=f'{SHOTS}/admin.png')
    # export / import round trip
    pg.evaluate("() => { document.getElementById('adm').style.display === 'none' && window.ADM_OPEN(true) }")
    cmd(pg, 'save export'); txt = pg.evaluate("() => { const d = document.getElementById('adm').lastChild; return [...document.getElementById('adm').firstChild.childNodes].map(n => n.textContent).filter(t => /^[A-Za-z0-9+/=]{80,}$/.test(t)).pop() || '' }")
    ok('save export prints a base64 blob', len(txt) > 80, len(txt))
    # online: refused
    w0 = pg.evaluate("() => TD.S.wallet"); pg.evaluate("() => { TD.NET.link = 'conn' }"); cmd(pg, 'coins 1'); ok('refused while online', pg.evaluate("() => TD.S.wallet") == w0 and 'أونلاين' in pg.evaluate(LOG))
    pg.evaluate("() => { TD.NET.link = 'off' }")
    cmd(pg, 'nonsense'); ok('unknown command is reported', 'غير معروف' in pg.evaluate(LOG))
    # ---- destructive commands (each reloads the page), and undo ----
    def relog():
        pg.wait_for_timeout(1500); pg.keyboard.press('Backquote'); pg.wait_for_timeout(150); cmd(pg, 'auth secret1')
    S2 = lambda e: pg.evaluate(f"() => {e}")
    pg.evaluate("() => { document.getElementById('adm').style.display === 'none' && window.ADM_OPEN(true) }")
    cmd(pg, 'gems 5'); cmd(pg, 'coins 321'); cmd(pg, 'wipe gems'); relog()
    ok('wipe gems (no yes needed): gems gone after the reload, coins kept, still marked admin', S2('TD.S.gems|0') == 0 and S2('TD.S.wallet') == 321 and S2('TD.S.adm') == 1)
    cmd(pg, 'undo'); relog(); ok('undo brings the gems back', S2('TD.S.gems') == 5 and S2('TD.S.wallet') == 321)
    cmd(pg, 'unlock heroes'); cmd(pg, 'hero robot'); cmd(pg, 'wipe heroes yes'); relog()
    ok('wipe heroes yes: back to the first hero only, other things (coins, gems) kept', S2("Object.keys(TD.S.own).join()") == 'falafel' and S2('TD.S.hero') == 'falafel' and S2('TD.S.wallet') == 321 and S2('TD.S.gems') == 5)
    cmd(pg, 'undo'); relog(); ok('undo brings the heroes back', S2('Object.keys(TD.S.own).length') >= 8 and S2('TD.S.hero') == 'robot')
    cmd(pg, 'best 30'); cmd(pg, 'wipe progress yes'); relog(); ok('wipe progress yes: level 1 again, no stars', S2('TD.S.best') == 1 and S2('Object.keys(TD.S.cl).length') == 0 and S2('TD.S.wallet') == 321)
    cmd(pg, 'undo'); relog(); ok('undo brings the progress back', S2('TD.S.best') == 30)
    cmd(pg, 'wipe shop yes'); relog(); ok('wipe shop yes empties the bought cosmetics', S2('Object.keys(TD.S.aq).length') == 0 and S2('Object.keys(TD.S.own).length') >= 8)
    cmd(pg, 'wipe ach yes'); relog(); ok('wipe ach yes: counters restart and achievements are worked out again from the progress (they pay again)', S2('typeof TD.S.st') == 'object' and S2('TD.S.st.d') == 0 and S2('Object.keys(TD.S.ac).length') > 0)
    wal = S2('TD.S.wallet')
    cmd(pg, 'wipe daily'); relog(); ok('wipe daily (no yes) puts today\'s tasks back fresh', S2('Object.keys(TD.S.dy.c).length') == 0)
    cmd(pg, 'wipe profile yes'); relog(); ok('wipe profile yes clears name + picture choice', S2("(TD.S.fname || '') + (TD.S.pf ? 'x' : '')") == '' or S2('TD.pfGet().a') == 'h')
    cmd(pg, 'reset yes'); relog()
    ok('reset yes: a fresh save (coins 0, level 1, no heroes) but the console word survives', S2('TD.S.wallet|0') == 0 and S2('TD.S.best') == 1 and S2('Object.keys(TD.S.own).join()') == 'falafel' and S2("typeof TD.S.admh") == 'number')
    cmd(pg, 'undo'); relog(); ok('undo after reset brings the whole save back', S2('TD.S.best') == 30 and S2('TD.S.gems') == 5 and S2('TD.S.wallet') == wal)
    cmd(pg, 'coins 1000'); cmd(pg, 'coins 2000'); cmd(pg, 'undo'); relog(); ok('undo takes back only the LAST command', S2('TD.S.wallet') == 1000)
    cmd(pg, 'undo'); relog(); cmd(pg, 'undo'); relog(); cmd(pg, 'undo'); pg.wait_for_timeout(300)
    ok('undo with nothing left says so and changes nothing', 'ما في شي' in pg.evaluate(LOG) or S2('TD.S.wallet') >= 0)
    ok('no page errors', not errs, errs[:3])
    b.close()
print('RESULT:', 'ALL OK' if all(res) else 'FAILURES')
sys.exit(0 if all(res) else 1)
